-- Cached secondary-source recent results for the final race's jockeys, trainers, and owners.
-- Empty result pages remain represented by source mappings rather than fabricated rows.
-- Source rows with an unpublished going preserve it as NULL.

begin;
on conflict (source, person_kind, source_person_id, source_race_id, source_horse_id) where source_horse_id is not null
do update set race_date=excluded.race_date, venue=excluded.venue, race_number=excluded.race_number, race_name=excluded.race_name, source_race_url=excluded.source_race_url, horse_name=excluded.horse_name, finish_position=excluded.finish_position, finish_position_text=excluded.finish_position_text, surface=excluded.surface, distance_metres=excluded.distance_metres, going=excluded.going, updated_at=now();

on conflict (source, person_kind, source_person_id, source_race_id, horse_name) where source_horse_id is null
do update set race_date=excluded.race_date, venue=excluded.venue, race_number=excluded.race_number, race_name=excluded.race_name, source_race_url=excluded.source_race_url, horse_name=excluded.horse_name, finish_position=excluded.finish_position, finish_position_text=excluded.finish_position_text, surface=excluded.surface, distance_metres=excluded.distance_metres, going=excluded.going, updated_at=now();
commit;
